def qualifying_child(facts):
    unit = 'u152_c1_pred'
    direct = facts.get('qualifying_child_under_152_c_1')
    if direct is not None:
        return {'value': direct, 'used_units': [unit], 'open_dependencies': []}

    relationship = facts.get('relationship_requirement_met_under_152_c_2')
    if relationship is None:
        first_group = facts.get('individual_is_child_or_descendant_of_child_of_taxpayer')
        second_group = facts.get('individual_is_sibling_stepsibling_or_descendant_of_such_relative_of_taxpayer')
        if first_group is True or second_group is True:
            relationship = True
        elif first_group is False and second_group is False:
            relationship = False
    if relationship is False:
        return {'value': False, 'used_units': [unit], 'open_dependencies': []}

    start = facts.get('shared_principal_abode_start_date')
    end = facts.get('shared_principal_abode_end_date')
    year = facts.get('query_year')
    if start is not None and end is not None and year is not None:
        abode = 2 * inclusive_year_overlap_days(start, end, year) > year_days(year)
    else:
        abode = facts.get('same_principal_abode_more_than_half_taxable_year')
    if abode is False:
        return {'value': False, 'used_units': [unit], 'open_dependencies': []}

    individual_age = facts.get('individual_age_at_end_of_taxable_year')
    taxpayer_age = facts.get('taxpayer_age_at_end_of_taxable_year')
    age_requirement = None
    if individual_age is not None and individual_age >= 25:
        age_requirement = False
    elif individual_age is not None and taxpayer_age is not None:
        age_requirement = individual_age < taxpayer_age
    if age_requirement is None:
        age_requirement = facts.get('age_requirement_met_under_152_c_3')
    if age_requirement is False:
        return {'value': False, 'used_units': [unit], 'open_dependencies': []}

    joint_return_condition = facts.get('joint_return_condition_met_under_152_c_1_E')
    if joint_return_condition is None:
        filed_joint_return = facts.get('individual_filed_joint_return_with_spouse', False)
        if filed_joint_return is False:
            joint_return_condition = True
        else:
            refund_only = facts.get('joint_return_filed_only_for_refund')
            if refund_only is not None:
                joint_return_condition = refund_only
    if joint_return_condition is False:
        return {'value': False, 'used_units': [unit], 'open_dependencies': []}

    open_dependencies = []
    if relationship is None:
        open_dependencies.append('The relationship requirement of section 152(c)(2) is unresolved.')
    if abode is None:
        open_dependencies.append('The more-than-one-half principal-abode requirement is unresolved; complete dates or an explicit scoped premise are required.')
    if age_requirement is None:
        open_dependencies.append('The age requirements of section 152(c)(3) are unresolved.')
    if joint_return_condition is None:
        open_dependencies.append('A stated joint return is unresolved as to whether it was filed only for a refund.')
    if open_dependencies:
        return {'value': None, 'used_units': [unit], 'open_dependencies': open_dependencies}
    return {'value': True, 'used_units': [unit], 'open_dependencies': []}

def surviving_spouse_recent_death(facts):
    unit = 'u2_a_1_A_pred'
    direct = facts.get('spouse_death_requirement_met_under_2_a_1_A')
    if direct is not None:
        return {'value': direct, 'used_units': [unit], 'open_dependencies': []}
    death_date = facts.get('spouse_date_of_death')
    year = facts.get('query_year')
    if death_date is None or year is None:
        return {'value': None, 'used_units': [unit], 'open_dependencies': ['The spouse death date and taxable year are required unless the scoped section 2(a)(1)(A) condition is explicitly GIVEN.']}
    death_year = calendar_year(death_date)
    return {'value': death_year == year - 1 or death_year == year - 2, 'used_units': [unit], 'open_dependencies': []}

